actions.script:
const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
const address = String(emailAddress || '').trim()
if (!['EakExternal', 'EakShared'].includes(accountKindEnumId)) accountKindEnumId = 'EakExternal'
// the account this wizard made for the same address: its own settings, not a new lookup
let settings = null
if (emailAccountId) {
    const detail = ec.service.sync().name('ironstone.MailSettingsServices.get#MailAccountDetail').parameter('emailAccountId', emailAccountId).call()
    if (ec.message.hasError()) return
    if (detail?.server && String(detail.account?.emailAddress || '').toLowerCase() === address.toLowerCase()) settings = Object.assign({source: 'saved'}, detail.server)
}
if (!settings) {
    const out = ec.service.sync().name('ironstone.MailSettingsServices.suggest#MailServer').parameter('emailAddress', address).call()
    if (ec.message.hasError()) return
    const suggestion = out?.suggestion || {}
    if (suggestion.unsupported) { ec.message.addError(suggestion.warningText || L('This provider cannot be added here')); return }
    settings = suggestion
}
emailAddress = address
displayName = String(displayName || '').trim()
storeKind = settings.storeKind || 'imap'
storeSecurity = settings.storeSecurity || 'ssl'
storeHost = settings.storeHost || ''
storePort = settings.storePort || ''
smtpHost = settings.smtpHost || ''
smtpPort = settings.smtpPort || ''
smtpSecurity = settings.smtpSecurity || 'starttls'
mailUsername = settings.mailUsername || address
// the outgoing server's own user, when the lookup says it signs in as another one
smtpUsername = settings.smtpUsername || ''
source = settings.source || 'guess'
oauthProvider = settings.oauthProviderEnumId || ''

if (fresh === 'Y') { emailAccountId = null; emailAddress = null; displayName = null; accountKindEnumId = null }
const userName = ec.user.userAccount?.userFullName || ''
address = {emailAccountId: emailAccountId || '', emailAddress: emailAddress || '', displayName: displayName || userName,
    accountKindEnumId: accountKindEnumId === 'EakShared' ? 'EakShared' : 'EakExternal'}
